package com.jiugeng.erp.product;
import static com.jiugeng.erp.product.ProductTypes.*;import java.math.BigDecimal;import java.sql.*;import java.time.Instant;import java.util.*;import org.springframework.jdbc.core.simple.JdbcClient;import org.springframework.stereotype.Repository;
@Repository class ProductRepository{private final JdbcClient jdbc;ProductRepository(JdbcClient jdbc){this.jdbc=jdbc;}
List<ProductView> findAll(boolean suppliers){return jdbc.sql("SELECT * FROM product ORDER BY product_code_normalized").query((r,n)->product(r,suppliers)).list();}
Optional<ProductView> findById(String id,boolean suppliers){return jdbc.sql("SELECT * FROM product WHERE id=:id").param("id",id).query((r,n)->product(r,suppliers)).optional();}
boolean productCodeExists(String code,String excluding){return count("SELECT COUNT(*) FROM product WHERE product_code_normalized=:value"+(excluding==null?"":" AND id<>:id"),code,excluding);}
boolean skuCodeExists(String code,String excluding){return count("SELECT COUNT(*) FROM product_variant WHERE sku_code_normalized=:value"+(excluding==null?"":" AND id<>:id"),code,excluding);}
boolean variantBelongsToProduct(String variant,String product){return jdbc.sql("SELECT COUNT(*) FROM product_variant WHERE id=:id AND product_id=:product").param("id",variant).param("product",product).query(Integer.class).single()>0;}
List<String> findVariantIds(String product){return jdbc.sql("SELECT id FROM product_variant WHERE product_id=:id").param("id",product).query(String.class).list();}
void insertProduct(String id,String code,String normalized,String name,String type,String description,ProductStatus status,String actor){jdbc.sql("INSERT INTO product(id,product_code,product_code_normalized,name_zh,product_name,product_type,description,status,created_by,updated_by) VALUES(:id,:code,:normalized,:name,:name,:type,:description,:status,:actor,:actor)").param("id",id).param("code",code).param("normalized",normalized).param("name",name).param("type",type).param("description",description).param("status",status.name()).param("actor",actor).update();}
int updateProduct(String id,String name,String type,String description,ProductStatus status,long version,String actor){return jdbc.sql("UPDATE product SET product_name=:name,name_zh=:name,product_type=:type,description=:description,status=:status,version=version+1,updated_by=:actor,updated_at=CURRENT_TIMESTAMP WHERE id=:id AND version=:version").param("id",id).param("name",name).param("type",type).param("description",description).param("status",status.name()).param("actor",actor).param("version",version).update();}
void insertVariant(String id,String product,String sku,String normalized,String name,String itemDimensions,String packageDimensions,BigDecimal grams,VariantStatus status,String image,String imageUrl,String signature){jdbc.sql("INSERT INTO product_variant(id,product_id,sku_code,sku_code_normalized,variant_name,item_dimensions,package_dimensions,package_weight_grams,lifecycle_status,main_image_asset_id,main_image_url,status,attribute_signature) VALUES(:id,:product,:sku,:normalized,:name,:item,:package,:grams,:lifecycle,:image,:imageUrl,:legacy,:signature)").param("id",id).param("product",product).param("sku",sku).param("normalized",normalized).param("name",name).param("item",itemDimensions).param("package",packageDimensions).param("grams",grams).param("lifecycle",status.name()).param("image",image).param("imageUrl",imageUrl).param("legacy",status==VariantStatus.DISABLED?"DISABLED":"ACTIVE").param("signature",signature).update();}
int updateVariant(String id,String sku,String normalized,String name,String itemDimensions,String packageDimensions,BigDecimal grams,VariantStatus status,String image,String imageUrl,long version){return jdbc.sql("UPDATE product_variant SET sku_code=:sku,sku_code_normalized=:normalized,variant_name=:name,item_dimensions=:item,package_dimensions=:package,package_weight_grams=:grams,lifecycle_status=:lifecycle,main_image_asset_id=:image,main_image_url=:imageUrl,status=:legacy,version=version+1,updated_at=CURRENT_TIMESTAMP WHERE id=:id AND version=:version").param("id",id).param("sku",sku).param("normalized",normalized).param("name",name).param("item",itemDimensions).param("package",packageDimensions).param("grams",grams).param("lifecycle",status.name()).param("image",image).param("imageUrl",imageUrl).param("legacy",status==VariantStatus.DISABLED?"DISABLED":"ACTIVE").param("version",version).update();}
void disableVariant(String id){jdbc.sql("UPDATE product_variant SET lifecycle_status='DISABLED',status='DISABLED',version=version+1,updated_at=CURRENT_TIMESTAMP WHERE id=:id").param("id",id).update();}
int disableProduct(String id,long version,String actor){return jdbc.sql("UPDATE product SET status='DISABLED',version=version+1,updated_by=:actor,updated_at=CURRENT_TIMESTAMP WHERE id=:id AND version=:version").param("id",id).param("version",version).param("actor",actor).update();}
private ProductView product(ResultSet r,boolean includeSuppliers)throws SQLException{String id=r.getString("id");List<VariantView> variants=jdbc.sql("SELECT * FROM product_variant WHERE product_id=:id ORDER BY sku_code_normalized").param("id",id).query((row,n)->variant(row,includeSuppliers)).list();String productName=r.getString("product_name");if(productName==null||productName.isBlank())productName=r.getString("name_zh");if(productName==null||productName.isBlank())productName=r.getString("name_en");return new ProductView(id,r.getString("product_code"),productName,r.getString("name_zh"),r.getString("name_en"),r.getString("brand"),r.getString("internal_category"),r.getString("product_type"),r.getString("description"),ProductStatus.valueOf(r.getString("status")),r.getLong("version"),variants,variants.size(),includeSuppliers,instant(r,"created_at"),instant(r,"updated_at"));}
private VariantView variant(ResultSet r,boolean includeSuppliers)throws SQLException{String id=r.getString("id");List<AttributeView> attrs=jdbc.sql("SELECT attribute_code,attribute_value,display_order FROM variant_attribute WHERE variant_id=:id ORDER BY display_order,attribute_code_normalized").param("id",id).query((row,n)->new AttributeView(row.getString(1),row.getString(2),row.getInt(3))).list();List<SupplierAssignment> suppliers=includeSuppliers?jdbc.sql("SELECT supplier_id,purchase_url,remark,primary_slot FROM product_variant_supplier WHERE variant_id=:id ORDER BY CASE WHEN primary_slot='PRIMARY' THEN 0 ELSE 1 END,id").param("id",id).query((row,n)->new SupplierAssignment(row.getString(1),row.getString(2),row.getString(3),"PRIMARY".equals(row.getString(4)))).list():List.of();List<MaterialAssignment> materials=jdbc.sql("SELECT auxiliary_material_id,standard_quantity,unit,loss_rate,remark,enabled FROM product_auxiliary_material WHERE variant_id=:id ORDER BY auxiliary_material_id").param("id",id).query((row,n)->new MaterialAssignment(row.getString(1),row.getBigDecimal(2),row.getString(3),row.getBigDecimal(4),row.getString(5),row.getBoolean(6))).list();return new VariantView(id,r.getString("sku_code"),r.getString("variant_name"),r.getString("barcode"),r.getString("material"),r.getString("specification"),r.getString("item_dimensions"),r.getString("package_dimensions"),r.getBigDecimal("package_weight"),r.getString("package_weight_unit"),r.getBigDecimal("package_weight_grams"),VariantStatus.valueOf(r.getString("lifecycle_status")),r.getString("main_image_asset_id"),r.getString("main_image_url"),r.getLong("version"),attrs,suppliers,materials);}
private boolean count(String sql,String value,String id){var q=jdbc.sql(sql).param("value",value);if(id!=null)q=q.param("id",id);return q.query(Integer.class).single()>0;}
private Instant instant(ResultSet r,String c)throws SQLException{return r.getTimestamp(c).toInstant();}
static String normalize(String value){return value.trim().toUpperCase(Locale.ROOT);}
}
